-- Adds the standard disclaimer line to 51 wait-verdict review pages with no retailer link, and sets their variant.
DO $$ BEGIN RAISE EXCEPTION 'HOLD: do not run.'; END $$;
update public.reviews
set content = regexp_replace(
      content,
      '(^|\n\n)(Verdict: WAIT\.[^\n]*)(\n\n|$)',
      E'\\1\\2\n\n' || $d$Standard disclaimer: rich readers can skip the verdict and just buy it. The rest of us will be here doing sums before we hit checkout.$d$ || E'\\3'
    ),
    verdict_disclaimer_variant = 'wait_unlisted'
where (slug, md5(content)) in (values ('lego-40875-up-scaled-mrs-claus-minifigure-worth-5700','7216710a019de0a66f844a2b3b304288'), ('lego-77264-jaguar-project-7-land-rover-defender-worth-5999','17c2d06fe566fdaf1420adade0d853d0'), ('lego-acclamator-class-assault-ship-75404-worth-5449','096abb2ce116edcfa7fdad826c6ea786'), ('lego-audi-rs-q-e-tron-42160-worth-17999','edfd67134a1312e9d7a56fe533a588f0'), ('lego-beekeepers-house-and-flower-garden-42669-worth-10999','87d71de36228480a6bf8d38651e1d446'), ('lego-bmw-m3-e30-77263-worth-2999','cae4afcb1c44222445c8564b2a552a0f'), ('lego-botanicals-10371-cozy-plants-is-it-worth-2200','577991d1930b9fa6fc9c0f0c24b4b58b'), ('lego-build-a-minifigure-2026-halloween-haul-or-heartbreak','cd9dd719835ac0fa18944ef45de15723'), ('lego-cubone-and-gengars-spooky-showdown-72166-worth-8600','a90e7e80910574adc4ad7a0108a75943'), ('lego-douglas-dc-3-pan-am-airliner-11378-worth-21999','74ccd2369414b3eeb8e25210951f7263'), ('lego-dragon-ball-shenron-goku-11390-a-nostalgic-build-for-th','7c3b1aab2c72b3396c597aa3dc536d30'), ('lego-dragon-stone-shrine-71819-worth-11899','881a0b724c0f083a4e97f5464d0b8ae4'), ('lego-dungeons-dragons-red-dragons-tale-21348-worth-35999','16c4ba4469f12e65c24b94547ceb79ee'), ('lego-executor-super-star-destroyer-75457-worth-76500','13f78242e540642b6fb811b72c533c86'), ('lego-fountain-garden-10359-worth-5499','85b005325062489d68686fbc49c223cd'), ('lego-great-deku-tree-77092-worth-20399','a4757992ba166ebdfa2979c181808b92'), ('lego-hagrid-harrys-motorcycle-ride-76443-worth-5449','cd0852dbd86bef1cc3ead67e93a2c209'), ('lego-icons-11387-holiday-house-does-this-winter-village-set-','2028f8923fcf159895604f4da4f35ad1'), ('lego-ideas-21365-love-birds-worth-5499','1236c9062748bd41c5dd3b310689823c'), ('lego-ideas-21373-downton-abbey-worth-33600','bfb9617ce865353cfb9582c58154cd62'), ('lego-ideas-21373-downton-abbey-worth-the-wait','a5c7da46458173b2a7aac0cb8ef1142d'), ('lego-kais-ninja-climber-mech-71812-worth-6399','e70d60585ffb6bd62f0a48f0ef2